 import type { Metadata, Viewport } from "next";
import { Geist } from "next/font/google";
// UploadThing ships its own Tailwind utilities (e.g. `.hidden`); import it before globals.css
// so our responsive variants like `lg:block` aren't overridden by it.
import "@uploadthing/react/styles.css";
import "./globals.css";
// Light/dark colour variables (generated by scripts/generate-theme.mjs)
import "./theme.css";
import { Providers } from "@/components/providers";
import { SITE_NAME, SITE_URL } from "@/lib/site";
import { themeInitScript } from "@/lib/theme";
import PwaRegister from "@/components/pwa/PwaRegister";
import SplashScreen from "@/components/pwa/SplashScreen";
import { splashInitScript } from "@/lib/splash";

const geist = Geist({ subsets: ["latin"] });

export const viewport: Viewport = {
  // Colours the phone's status bar and the installed app's title bar
  themeColor: "#0f172a",
};

export const metadata: Metadata = {
  metadataBase: new URL(SITE_URL),
  applicationName: "AutoGO",
  // iPhone: open full screen from the home screen, under the name "AutoGO"
  appleWebApp: { capable: true, title: "AutoGO", statusBarStyle: "default" },
  title: {
    default: "AutoGO — Buy, Sell & Rent Vehicles",
    template: "%s — AutoGO",
  },
  description: "Pakistan's premier automobile marketplace",
  icons: {
    // The AutoGO mark (three slashes over the car), all on transparent: the white-backed icon-192 is for the
    // installed app only, or high-resolution screens would pick it and show a white box in the tab
    icon: [
      { url: "/icons/favicon-32.png", sizes: "32x32", type: "image/png" },
      { url: "/icons/favicon-48.png", sizes: "48x48", type: "image/png" },
      { url: "/icons/favicon-96.png", sizes: "96x96", type: "image/png" },
      { url: "/icons/favicon-192.png", sizes: "192x192", type: "image/png" },
    ],
    // iPhone home-screen icon (installed app)
    apple: [{ url: "/icons/apple-touch-icon.png", sizes: "180x180" }],
  },
  openGraph: {
    siteName: SITE_NAME,
    type: "website",
    locale: "en_PK",
  },
  twitter: { card: "summary_large_image" },
};

export default function RootLayout({
  children,
}: {
  children: React.ReactNode;
}) {
  return (
    // The <head> script sets the `dark` class before React hydrates, hence suppressHydrationWarning
    <html lang="en" suppressHydrationWarning>
      <head>
        <script dangerouslySetInnerHTML={{ __html: themeInitScript }} />
        <script dangerouslySetInnerHTML={{ __html: splashInitScript }} />
      </head>
      <body className={geist.className}>
        <SplashScreen />
        <Providers>{children}</Providers>
        <PwaRegister />
      </body>
    </html>
  );
}